#include "game.hpp"
#include "json.hpp"
#include <filesystem>
#include <fstream>
#include <iostream>
#include <limits>
#include <stdexcept>
using namespace hyperion;
namespace {
int checks=0;void check(bool ok,const char* why){++checks;if(!ok)throw std::runtime_error(why);}bool near(double a,double b){return std::abs(a-b)<1e-7;}
nlohmann::json snapshot(const State& s){auto f=std::filesystem::temp_directory_path()/"hyperion-turn-planner-test.json";std::string error;check(saveState(s,f.string(),error),"snapshot save");std::ifstream in(f);nlohmann::json j;in>>j;in.close();std::filesystem::remove(f);return j;}
void quiet(Game& g){g.ensureEconomy();g.s.mode=Mode::System;g.s.economy.routes.clear();g.s.economy.contracts.clear();g.s.economy.missions.clear();g.s.economy.pirates.clear();for(auto& p:g.s.economy.settlements)p.owner=1;}
void freight(Game& g,double eta,bool full=false){quiet(g);auto& e=g.s.economy;auto& a=e.settlements[0];auto& b=e.settlements[1];for(auto* s:{&a,&b}){s->owner=0;s->residents=0;s->stock={};s->built={};s->built[Warehouse]=2;s->loyalty=100;s->alerts=0;}if(full)b.stock[Ore]=storageCapacity(b);TradeRoute r;r.id="TEST-FREIGHT";r.from=a.id;r.to=b.id;r.good=Rations;r.outbound=true;r.enabled=false;r.remaining=eta;r.cargo[Rations]=8;e.routes.push_back(r);}
}
int main(){try{
 Game g;freight(g,2.25);auto& e=g.s.economy;Contract c;c.id="TIMED";c.settlement=e.settlements[1].id;c.accepted=true;c.deadline=4.5;e.contracts.push_back(c);e.research=0;e.researchProgress=technologies[0].hours-.35;Mission offered;offered.id="OFFER";offered.state=MissionOffered;offered.deadline=.1;e.missions.push_back(offered);
 auto frozen=snapshot(g.s);auto list=g.upcoming();check(list.size()==3,"Timeline includes research, freight and accepted deadline, excluding unaccepted offers");check(near(list[0].hours,1)&&list[0].estimate,"Research ETA uses actual base research rate and is explicitly an estimate");check(near(list[1].hours,2.25)&&!list[1].estimate&&list[1].settlement==e.settlements[1].id,"Freight timeline uses actual remaining travel and links its destination");check(near(list[2].hours,4.5),"Deadline is relative to campaign time");
 for(int i=0;i<100;i++){g.upcoming(i%2?6:24);g.outlook(12);g.orderHint("waitTurns","12");}check(snapshot(g.s)==frozen,"Planning queries preserve the entire campaign");check(g.upcoming(2).size()==1&&g.upcoming(0).empty()&&g.upcoming(std::numeric_limits<double>::quiet_NaN()).empty(),"Timeline horizon filters safely");
 e.research=-1;e.contracts.clear();g.s.hours=0;g.action("waitTurns","next");check(near(g.s.hours,3)&&g.s.turns==3,"Next-event wait resolves a fractional arrival at the next full hour");check(g.lastTurn.interruption.find("Freight arrived")!=std::string::npos&&g.lastTurn.requested==24,"Arrival stops the wait with an explicit requested duration and cause");check(e.routes[0].trips==1&&near(e.settlements[1].stock[Rations],8),"Interrupted wait delivered real conserved cargo");check(g.upcoming().empty(),"Delivered freight is removed from the timeline");
 double hour=g.s.hours;g.waitPlanned("3");check(near(g.s.hours,hour+3)&&g.lastTurn.interruption.empty(),"Old arrival cannot repeatedly interrupt future waits");
 Game held;freight(held,.25,true);held.waitPlanned("6");check(held.s.hours==1&&held.lastTurn.interruption.find("Freight held")!=std::string::npos,"Warehouse-full arrival interrupts with a useful explanation");hour=held.s.hours;held.waitPlanned("3");check(held.s.hours==hour+3,"An unchanged known freight hold does not repeatedly interrupt");
 Game research;quiet(research);research.s.economy.research=0;research.s.economy.researchProgress=technologies[0].hours-.1;research.waitPlanned("next");check(research.s.hours==1&&research.s.economy.researched[0]&&research.lastTurn.interruption.find("Research completed")!=std::string::npos,"Actual research completion interrupts next-event waiting");check(research.recentTurns.size()==1&&research.recentTurns[0].endHour==1,"Recent resolution is recorded exactly once");
 Game exact;quiet(exact);exact.s.economy.research=0;exact.s.economy.researchProgress=technologies[0].hours-.1;exact.waitPlanned("1");check(exact.lastTurn.interruption.empty()&&exact.lastTurn.hours==exact.lastTurn.requested,"Event on the final requested hour is completion, not an early interruption");check(std::any_of(exact.lastTurn.events.begin(),exact.lastTurn.events.end(),[](const auto& s){return s.find("Research completed")!=std::string::npos;}),"Final-hour completion remains in the report");
 Game invalid;quiet(invalid);frozen=snapshot(invalid.s);for(const auto& arg:{"","0","2","25","-6","3garbage","nan","inf"})invalid.action("waitTurns",arg);check(snapshot(invalid.s)==frozen&&invalid.recentTurns.empty(),"Invalid planned waits spend no time or resources");invalid.issueOrder("waitTurns","3",true);check(snapshot(invalid.s)==frozen,"Pause blocks planned waits");invalid.enterFlight();frozen=snapshot(invalid.s);invalid.waitPlanned("3");check(snapshot(invalid.s)==frozen,"Turn planner cannot fast-forward live flight");
 Game history;quiet(history);for(int i=0;i<16;i++)history.endTurn();check(history.recentTurns.size()==12&&history.recentTurns.front().last==16&&history.recentTurns.back().last==5,"Recent history is bounded, newest first and retains distinct turns");for(const auto& r:history.recentTurns)check(near(r.endHour-r.startHour,r.hours)&&r.hours==r.requested,"Report interval matches its actual resolved duration");history.reset("NEW");check(history.recentTurns.empty()&&!history.lastTurn.valid,"New campaign clears old turn reports");
 Game waypoint;waypoint.system("HOME");waypoint.s.selectedPlanet=2;check(waypoint.descend(),"Surface fixture deploys");waypoint.s.waypoint={waypoint.s.surface.x+110,waypoint.s.surface.y+30};auto target=waypoint.s.waypoint;waypoint.waitPlanned("1");check(waypoint.s.waypoint.x==target.x&&waypoint.s.waypoint.y==target.y&&waypoint.planMove().valid,"Waiting to recharge preserves the planned surface route");check(waypoint.dive(),"Ocean fixture deploys");waypoint.s.oceanTargetX=waypoint.s.oceanX+90;waypoint.s.targetDepth=std::min(waypoint.maxDepth(),waypoint.s.depth+200);double x=waypoint.s.oceanTargetX,depth=waypoint.s.targetDepth;waypoint.waitPlanned("1");check(waypoint.s.oceanTargetX==x&&waypoint.s.targetDepth==depth&&waypoint.planMove().valid,"Waiting preserves the dive route");
 Game cost;cost.system("HOME");cost.s.selectedPlanet=2;cost.descend();cost.s.battery=50;double start=cost.s.hours;cost.issueOrder("scan");check(near(cost.lastTurn.battery,-8)&&near(cost.lastTurn.startHour,start)&&cost.recentTurns.front().battery==-8,"Issued scan report includes scanner expenditure and recovery exactly once");
 cost.system("HOME");start=cost.s.hours;auto count=cost.recentTurns.size();cost.issueOrder("dock",cost.s.economy.settlements.front().id);check(cost.s.hours>start&&near(cost.lastTurn.startHour,start)&&near(cost.lastTurn.hours,cost.s.hours-start)&&cost.recentTurns.size()==count+1,"A recovery plus orbital rendezvous is reported as one complete issued order");
 waypoint.s.depth=waypoint.maxDepth()+100;double oldHull=waypoint.s.hull;check(waypoint.planMove({0,1},false).impact,"Impact fixture reaches its depth boundary");waypoint.moveTurn({0,1});check(near(waypoint.lastTurn.hull,waypoint.s.hull-oldHull),"Movement report includes boundary impact and pressure damage together");
 Game offset;freight(offset,2.25);offset.s.hours=.1;auto eta=offset.upcoming();check(eta.size()==1&&near(eta[0].hours,2.15),"Freight ETA accounts for a partial economic tick after cockpit flight");
 Game navigator;quiet(navigator);navigator.enterFlight();auto& nf=navigator.s.flight;nf.traffic.clear();int berth=navigator.flightPort(navigator.s.economy.settlements.front().id,true);nf.selectTarget(berth);nf.docked=false;nf.dockedPort=-1;nf.deployed=false;nf.ship.position=nf.ports[berth].position+nf.ports[berth].normal*110;nf.ship.previous=nf.ship.position;nf.ship.velocity={};nf.ship.throttle=0;nf.navigate();navigator.system(navigator.s.currentStar);navigator.waitPlanned("next");check(nf.docked&&navigator.lastTurn.hours<24&&navigator.lastTurn.interruption.find("Navigator reached berth")!=std::string::npos,"Physical navigator docking returns control before a day passes");
 Game threat;quiet(threat);threat.enterFlight();auto& tf=threat.s.flight;tf.traffic.clear();tf.docked=false;tf.dockedPort=-1;tf.deployed=false;tf.cancelNavigation();tf.ship.position={-10000,20000,0};tf.ship.previous=tf.ship.position;tf.ship.velocity={};tf.ship.throttle=0;tf.orient({0,0,-1},{0,1,0});hyperion::flight::Traffic enemy;enemy.id="INBOUND-THREAT";enemy.kind=1;enemy.role=1;enemy.hostile=true;enemy.position=enemy.previous=tf.ship.position+tf.ship.forward*1500;enemy.positioned=true;enemy.fireClock=1e6;enemy.ammunition=180;tf.traffic.push_back(enemy);threat.system(threat.s.currentStar);threat.waitPlanned("next");check(threat.lastTurn.hours<24&&threat.lastTurn.interruption.find("New armed contact")!=std::string::npos,"A previously distant physical hostile interrupts on entering threat range");
 Game npc;freight(npc,.25);for(auto& p:npc.s.economy.settlements)p.owner=1;npc.s.economy.routes[0].owner=1;check(npc.upcoming().empty(),"Other factions' unrelated freight does not clutter the timeline");npc.waitPlanned("3");check(npc.s.hours==3,"Unrelated arrivals do not interrupt player time");
 std::cout<<"PASS: "<<checks<<" turn planner checks / read-only timelines, real arrivals, research, held freight, exact durations, bounded history, rejected orders and preserved waypoints\n";return 0;
}catch(const std::exception& e){std::cerr<<"Turn planner failure after "<<checks<<" checks: "<<e.what()<<'\n';return 1;}}
